package com.hmdp.ai.application.mcp;import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.application.dto.mcp.CreateMcpServerRequest;import com.hmdp.ai.application.security.AiAccessGuard;import com.hmdp.ai.domain.mcp.*;import com.hmdp.ai.domain.security.*;import com.hmdp.ai.shared.id.AiIdGenerator;import org.junit.jupiter.api.Test;import java.util.EnumSet;import static org.assertj.core.api.Assertions.assertThatThrownBy;import static org.mockito.Mockito.*;
class McpApplicationServiceTest {@Test void nonAdminCannotRegisterMcpServer(){McpRepository repository=mock(McpRepository.class);AiAccessGuard access=mock(AiAccessGuard.class);AiSecurityContext context=new AiSecurityContext("user",new TenantContext("t"),new WorkspaceContext("w"),new AuthorizationContext(EnumSet.of(AiPermission.MCP_MANAGE)),false);when(access.require(AiPermission.MCP_MANAGE)).thenReturn(context);CreateMcpServerRequest request=new CreateMcpServerRequest();request.setCode("docs");request.setName("Docs");request.setNamespace("docs");request.setTransport(McpTransport.HTTP);request.setEndpoint("https://example.com/mcp");McpApplicationService service=new McpApplicationService(repository,access,new AiIdGenerator(),new ObjectMapper(),mock(McpManagementPort.class));assertThatThrownBy(()->service.create(request)).isInstanceOf(IllegalArgumentException.class).hasMessage("ADMIN_REQUIRED");verifyNoInteractions(repository);}}
